const rotation = [
  { niche: 'Umroh', target_audience: 'jamaah umroh', content_hint: 'persiapan dan pelaksanaan umroh' },
  { niche: 'Muthowif', target_audience: 'jamaah yang mencari pendamping ibadah', content_hint: 'memilih muthowif dan peran pendamping' },
  { niche: 'Travel Umroh', target_audience: 'calon jamaah Indonesia', content_hint: 'tips perjalanan dan itinerary Tanah Suci' },
  { niche: 'Kesehatan Jamaah', target_audience: 'jamaah lansia dan keluarga', content_hint: 'kesehatan dan stamina saat ibadah' },
  { niche: 'Etika Ibadah', target_audience: 'jamaah pemula', content_hint: 'adab dan etika di Masjidil Haram dan Nabawi' },
  { niche: 'Makkah & Madinah', target_audience: 'jamaah umroh', content_hint: 'ziyarah dan lokasi penting di Tanah Suci' },
  { niche: 'Paket Umroh', target_audience: 'calon jamaah', content_hint: 'memahami komponen paket umroh tanpa hard-sell' }
];

const languageInput = $json?.body?.language;
const language = Array.isArray(languageInput)
  ? languageInput
  : (languageInput ? [String(languageInput)] : ['Indonesia', 'English']);

const keywords = String($json?.body?.keywords ?? '').trim();
const autoTopic = !keywords;
const bodyNiche = String($json?.body?.niche ?? '').trim();

let niche = bodyNiche || 'Umroh';
let targetAudience = String($json?.body?.target_audience ?? 'jamaah umroh');
let contentHint = String($json?.body?.content_hint ?? '').trim();

if (autoTopic && (!bodyNiche || bodyNiche === 'Umroh')) {
  const picked = rotation[new Date().getDay() % rotation.length];
  niche = picked.niche;
  targetAudience = picked.target_audience;
  contentHint = picked.content_hint;
}

return [
  {
    json: {
      niche,
      keywords,
      target_audience: targetAudience,
      content_hint: contentHint,
      language,
      auto_topic: autoTopic,
      auto_publish: true,
      source: String($json?.body?.source ?? $json?.source ?? 'automation')
    }
  }
];

const makeSlug = (title) => String(title || '')
  .toLowerCase()
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .slice(0, 120);

const fail = (errors, preview = '') => ({
  json: {
    _is_valid: false,
    _errors: errors,
    _raw_preview: preview.slice(0, 1200),
    _revision_round: Number($json._revision_round ?? 0)
  }
});

const finishReason = $json.candidates?.[0]?.finishReason || $json.candidates?.[0]?.finish_reason || '';
const rawText = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
if (!rawText.trim()) {
  return fail([`Output AI kosong${finishReason ? ` (finishReason: ${finishReason})` : ''}`]);
}

const cleanText = rawText.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
const start = cleanText.indexOf('{');
const end = cleanText.lastIndexOf('}');

if (start === -1 || end === -1 || end <= start) {
  const reasonText = finishReason ? `Output AI terpotong (finishReason: ${finishReason})` : 'AI output tidak mengandung JSON object valid';
  return fail([reasonText], cleanText);
}

const jsonText = cleanText.slice(start, end + 1);

let data;
try {
  data = JSON.parse(jsonText);
} catch (error) {
  const normalized = jsonText.replace(/\r?\n/g, '\\n');
  try {
    data = JSON.parse(normalized);
  } catch (fallbackError) {
    return fail([`JSON AI invalid: ${fallbackError.message}${finishReason ? ` (finishReason: ${finishReason})` : ''}`], jsonText);
  }
}

const requiredFields = [
  'title', 'excerpt', 'category', 'author', 'body_md',
  'title_en', 'excerpt_en', 'category_en', 'author_en', 'body_md_en'
];

const errors = [];
for (const field of requiredFields) {
  if (data[field] === undefined || data[field] === null || String(data[field]).trim() === '') {
    errors.push(`Field wajib kosong: ${field}`);
  }
}

const bodyMd = String(data.body_md ?? '').trim();
const bodyMdEn = String(data.body_md_en ?? '').trim();

if (bodyMd.length < 600) errors.push('body_md terlalu pendek (< 600 karakter)');
if (bodyMdEn.length < 600) errors.push('body_md_en terlalu pendek (< 600 karakter)');

const title = String(data.title ?? '').trim();
const slug = String(data.slug ?? '').trim() || makeSlug(title);

if (!slug) errors.push('Slug gagal dibuat');

const payload = {
  title,
  slug,
  excerpt: String(data.excerpt ?? '').trim(),
  category: String(data.category ?? 'Umroh').trim(),
  author: String(data.author ?? 'BaytGo').trim(),
  body_md: bodyMd,

  auto_publish: true,
  is_featured: data.is_featured ?? false,
  sort_order: Number.isFinite(Number(data.sort_order)) ? Number(data.sort_order) : 0,

  title_en: String(data.title_en ?? '').trim(),
  excerpt_en: String(data.excerpt_en ?? '').trim(),
  category_en: String(data.category_en ?? 'Umrah').trim(),
  author_en: String(data.author_en ?? 'BaytGo').trim(),
  body_md_en: bodyMdEn
};

try {
  const research = $('Attach Research').item.json;
  const cover = String(research.image_url || '').trim();
  const covers = Array.isArray(research.image_urls) ? research.image_urls : [];
  if (cover) payload.image_url = cover;
  if (covers.length) payload.image_urls = covers.filter(Boolean);
} catch (e) {}

return {
  json: {
    ...payload,
    _is_valid: errors.length === 0,
    _errors: errors,
    _revision_round: Number(data.revision_round ?? $json._revision_round ?? 0)
  }
};

// Key Gemini dibaca dari environment n8n, dipisah koma.
// Di n8n Cloud $env diblokir: isi array `fallback` di bawah bila perlu.
const fallback = [];

let raw = '';
try {
  raw = String($env.GEMINI_API_KEYS || '');
} catch (e) {
  raw = '';
}

const keys = raw
  .split(',')
  .map((k) => k.trim())
  .filter(Boolean)
  .concat(fallback);

if (keys.length === 0) {
  throw new Error('GEMINI_API_KEYS belum diset di environment n8n.');
}

const index = Math.floor(Math.random() * keys.length);

return {
  json: {
    ...$json,
    geminiKey: keys[index],
    geminiKeyIndex: index,
    _meta: {
      selectedGeminiKey: index,
      totalGeminiKeys: keys.length
    }
  }
};

