const fail = (errors, preview = '') => ({
  json: {
    topic: '',
    angle: '',
    search_query: [String($('Data From User').item.json.niche || 'Umroh'), 'umroh muthowif jamaah BaytGo'].join(' '),
    category: 'Umroh',
    why_relevant: '',
    geminiKey: $('Prepare AI Key').item.json.geminiKey,
    _topic_ok: false,
    _topic_errors: errors,
    _topic_preview: String(preview).slice(0, 800)
  }
});

const rawText = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
if (!String(rawText).trim()) {
  return fail(['Propose Topic: output AI kosong']);
}

const cleanText = String(rawText).replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
const start = cleanText.indexOf('{');
const end = cleanText.lastIndexOf('}');
if (start === -1 || end === -1 || end <= start) {
  return fail(['Propose Topic: JSON tidak ditemukan'], cleanText);
}

let data;
try {
  data = JSON.parse(cleanText.slice(start, end + 1));
} catch (e) {
  return fail([`Propose Topic: JSON invalid: ${e.message}`], cleanText);
}

const niche = String($('Data From User').item.json.niche || 'Umroh');
const keywords = String($('Data From User').item.json.keywords || '').trim();
const topic = String(data.topic || '').trim();
const angle = String(data.angle || '').trim();
const category = String(data.category || niche || 'Umroh').trim();
const why = String(data.why_relevant || '').trim();
let searchQuery = String(data.search_query || '').trim();

if (!topic) {
  return fail(['Propose Topic: field topic kosong'], cleanText);
}

if (!searchQuery) {
  searchQuery = [topic, niche, 'umroh muthowif jamaah', keywords].filter(Boolean).join(' ');
}

return {
  json: {
    topic,
    angle,
    search_query: searchQuery,
    category,
    why_relevant: why,
    geminiKey: $('Prepare AI Key').item.json.geminiKey,
    _topic_ok: true,
    _topic_errors: []
  }
};

const topic = $('Parse Proposed Topic').item.json;
const tavily = $json;

const collect = [];
const pushUrl = (v) => {
  if (!v) return;
  if (typeof v === 'string' && /^https?:\/\//i.test(v)) collect.push(v.trim());
  else if (typeof v === 'object' && typeof v.url === 'string' && /^https?:\/\//i.test(v.url)) {
    collect.push(v.url.trim());
  }
};

for (const img of (tavily.images || [])) pushUrl(img);
for (const r of (tavily.results || [])) {
  for (const img of (r.images || [])) pushUrl(img);
}

const isDirectImage = (url) => {
  const lower = url.toLowerCase();
  if (/\.(svg|ico|gif)(\?|$)/i.test(lower)) return false;
  if (/wikipedia\.org\/wiki\/|commons\.wikimedia\.org\/wiki\//i.test(lower)) return false;
  if (/favicon|sprite|logo|icon|1x1|pixel|avatar|badge/i.test(lower)) return false;
  return true;
};

const scored = [...new Set(collect)]
  .filter(isDirectImage)
  .map((url) => {
    const lower = url.toLowerCase();
    let score = 0;
    if (/\.(jpe?g|png|webp)(\?|$)/i.test(lower)) score += 5;
    if (/upload\.wikimedia\.org|images\.unsplash\.com|cdn\.pixabay\.com|images\.pexels\.com|i\.imgur\.com/i.test(lower)) score += 4;
    if (/\.(html?|php|aspx)(\?|$)/i.test(lower)) score -= 8;
    return { url, score };
  })
  .sort((a, b) => b.score - a.score);

const fallbacks = [
  'https://upload.wikimedia.org/wikipedia/commons/0/0e/Masjid_al-Haram_at_night.jpg',
  'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Kaaba_during_Hajj.jpg/1280px-Kaaba_during_Hajj.jpg'
];

const ranked = scored.map((x) => x.url).concat(fallbacks.filter((url) => !scored.some((x) => x.url === url)));
const image_url = ranked[0] || '';
const image_urls = ranked.slice(0, 6);

return {
  json: {
    topic: topic.topic,
    angle: topic.angle,
    search_query: topic.search_query,
    category: topic.category,
    why_relevant: topic.why_relevant,
    geminiKey: topic.geminiKey || $('Prepare AI Key').item.json.geminiKey,
    answer: tavily.answer ?? '',
    results: tavily.results ?? [],
    image_url,
    image_urls,
    image_candidates: image_urls,
    tavily_raw: {
      query: tavily.query,
      response_time: tavily.response_time,
      images_found: collect.length
    }
  }
};

const resp = $json;
const items = Array.isArray(resp?.data) ? resp.data : [];
const existing = items.map((row) => ({
  slug: String(row.slug || ''),
  title: String(row.title || ''),
  category: String(row.category || ''),
  is_published: row.is_published === true,
  url: String(row.url || '')
}));

const titles = existing
  .map((row) => row.title.trim())
  .filter(Boolean)
  .slice(0, 40);

// Tujuan tautan internal datang dari Laravel (link_targets), bukan dari daftar
// dedup, karena hanya halaman yang benar-benar terbit yang boleh ditautkan.
const targets = Array.isArray(resp?.link_targets) ? resp.link_targets : [];
const linkLines = targets
  .map((t) => {
    const p = String(t.path || '').trim();
    const title = String(t.title || '').trim();
    if (!p || !title) return '';
    const tag = String(t.kind || '') === 'article' ? '[artikel]' : '[layanan]';
    const desc = String(t.description || '').trim();
    return `${tag} ${title} -> ${p}${desc ? ` (${desc})` : ''}`;
  })
  .filter(Boolean);

const user = $('Data From User').item.json;

return {
  json: {
    ...user,
    existing_articles: existing,
    existing_titles_text: titles.length
      ? titles.map((title, index) => `${index + 1}. ${title}`).join('\n')
      : '(belum ada artikel)',
    existing_count: existing.length,
    link_targets: targets,
    link_targets_text: linkLines.length
      ? linkLines.join('\n')
      : '(belum ada halaman yang bisa ditautkan)',
    link_targets_count: linkLines.length
  }
};

// Webhook Discord dibaca dari environment n8n.
let DISCORD_WEBHOOK_URL = '';
try {
  DISCORD_WEBHOOK_URL = String($env.DISCORD_WEBHOOK_URL || '');
} catch (e) {}

const ADMIN_ARTICLES_URL = 'https://baytgo.id/admin/artikel';

const payload = $json;
const topicNode = $('Parse Proposed Topic').first()?.json || {};
const dedupNode = $('Prepare Dedup Context').first()?.json || {};

const status = String(payload.status || 'unknown');
const slug = String(payload.slug || '').trim();
const title = String(payload.title || topicNode.topic || '').trim();
const message = String(payload.message || '').trim();

const qa = payload.qa || payload._qa || {};
const score = qa.score ?? null;
const minScore = qa.min_score ?? null;
const published = payload.is_published === true;
const liveUrl = String(payload.url || (slug ? `https://baytgo.id/artikel/${slug}` : '')).trim();

const cut = (text) => String(text).slice(0, 1024);

const fields = [
  { name: 'Status', value: published ? 'Terbit' : status, inline: true },
  { name: 'Skor QA', value: `${score ?? '-'}${minScore !== null ? ` / min ${minScore}` : ''}`, inline: true },
  { name: 'Niche', value: String(dedupNode.niche || '-'), inline: true }
];

if (topicNode.topic) {
  fields.push({ name: 'Topik', value: cut(topicNode.topic), inline: false });
}

if (message) {
  fields.push({ name: 'Catatan', value: cut(message), inline: false });
}

// Tanpa tahap review, alasan kegagalan harus sampai ke Discord supaya tidak
// perlu membuka n8n untuk tahu kenapa hari ini tidak ada artikel.
if (!published) {
  const weak = (qa.notes || []).filter((note) => /\(\+0|dari \d+\)/.test(String(note)));
  const reasons = []
    .concat(qa.hard_fail_reasons || [])
    .concat(payload.errors || [])
    .concat(weak);

  if (reasons.length) {
    fields.push({
      name: 'Kenapa gagal',
      value: cut(reasons.slice(0, 6).map((r) => `• ${r}`).join('\n')),
      inline: false
    });
  }
}

const embed = {
  title: cut((published ? '🚀 ' : status === 'blocked' ? '⛔ ' : 'ℹ️ ') + (title || 'Tanpa judul')).slice(0, 256),
  color: published ? 3066993 : status === 'blocked' ? 15158332 : 9807270,
  fields,
  footer: { text: 'BaytGo Content Bot' },
  timestamp: new Date().toISOString(),
  description: published && liveUrl
    ? `[Buka artikel](${liveUrl}) · [Kelola di admin](${ADMIN_ARTICLES_URL})`
    : `[Kelola di admin](${ADMIN_ARTICLES_URL})`
};

if (published && liveUrl) {
  embed.url = liveUrl;
}

return {
  json: {
    ...payload,
    notify_enabled: DISCORD_WEBHOOK_URL.trim() !== '',
    discord_webhook_url: DISCORD_WEBHOOK_URL.trim(),
    discord_payload: { embeds: [embed] }
  }
};
